<div class="page-header"><h1>Disponibilidad</h1><p>Consulta qué máquinas están libres en las fechas de tu evento.</p></div><form method="get" class="disponibilidad-form"><div class="form-row"><div class="form-group"><label for="desde">Fecha de inicio</label><input type="date" id="desde" name="desde" value="<?= e($desde) ?>" min="<?= date('Y-m-d') ?>"></div><div class="form-group"><label for="hasta">Fecha de fin</label><input type="date" id="hasta" name="hasta" value="<?= e($hasta) ?>" min="<?= date('Y-m-d') ?>"></div><div class="form-group form-group-btn"><button type="submit" class="btn btn-primary">Consultar</button></div></div></form>
<?php if ($consultado): ?><div class="disponibilidad-resultado"><?php if (!$disponibles && !$ocupadas): ?><p class="empty-state">No hay máquinas registradas.</p><?php else: ?><?php foreach ([['Disponibles',$disponibles,'disponible'],['No disponibles',$ocupadas,'ocupada']] as [$heading,$items,$class]): if (!$items) continue; ?><h2 class="disponibilidad-titulo <?= $class ?>"><?= $heading ?> (<?= count($items) ?>)</h2><div class="card-grid"><?php foreach ($items as $m): ?><article class="card <?= $class === 'ocupada' ? 'card-ocupada' : '' ?>"><div class="card-img-wrap"><img src="<?= e($m['imagen_url']) ?>" alt="<?= e($m['nombre']) ?>" onerror="this.src='/img/placeholder.svg'"></div><div class="card-body"><span class="badge badge-<?= $class === 'disponible' ? 'disponible' : 'ocupada' ?>"><?= $class === 'disponible' ? 'Disponible' : 'No disponible' ?></span><span class="badge badge-<?= strtolower(e($m['categoria'])) ?>"><?= e($m['categoria']) ?></span><h3><?= e($m['nombre']) ?></h3><?php if ($class === 'disponible'): ?><div class="card-footer"><span class="price">Desde <?= price($m['precio_base']) ?>/día</span><a href="/solicitud.php?maquinaId=<?= (int)$m['id'] ?>&desde=<?= e($desde) ?>&hasta=<?= e($hasta) ?>" class="btn btn-primary btn-sm">Solicitar</a></div><?php endif; ?></div></article><?php endforeach; ?></div><?php endforeach; ?><?php endif; ?></div><?php endif; ?>
